import pandas as pd
import numpy as np

chassi = '1BZ310LAHMD005533'

print('--- DADOS M3 ---')
try:
    df_m3 = pd.read_parquet('data/dataset_ouro_potencial_chassi_v1.parquet')
    m3_row = df_m3[df_m3['PIN'].astype(str).str.contains(chassi)]
    if not m3_row.empty:
        print(m3_row[['PIN', 'Ano Fabricacao', 'Horimetro_Final', 'METODO_HORIMETRO', 'STATUS_USO', 'Dias_Desde_Horimetro']].to_dict('records'))
    else:
        print('Chassi não encontrado no M3')
except Exception as e:
    print('Erro lendo M3:', e)

print('\n--- DADOS OFICINA CACHE (VO1010) ---')
try:
    df_vo = pd.read_parquet('../01_DNA/data/cache_vo1010.parquet')
    vo_row = df_vo[df_vo['VO1_CHASSI'].astype(str).str.contains(chassi)]
    if not vo_row.empty:
        print(vo_row.to_dict('records'))
    else:
        print('Chassi não encontrado no cache da oficina.')
except Exception as e:
    print('Erro lendo cache VO1010:', e)
"

