def extract(shared_data_dir: Path) -> dict:
    raw: dict = {}

    paths = {
        "faturamento": shared_data_dir / "dataset_ouro_faturamento_v1.parquet",
        "potencial":   shared_data_dir / "dataset_ouro_potencial_v1.parquet",
