    }

    for key, path in paths.items():
        if path.exists():
            raw[key] = pd.read_parquet(path)
            log.info("%s carregado: %d registros.", key, len(raw[key]))
        else:
            log.error("Arquivo nao encontrado: %s", path)
            raw[key] = pd.DataFrame()

