    if path_vendas.exists():
        raw["vendas"] = pd.read_parquet(path_vendas)
        log.info("Vendas RFM carregadas: %d registros.", len(raw["vendas"]))
    else:
        log.warning("cache_vendas_rfm.parquet nao encontrado â€” RFM sera ignorado.")
        raw["vendas"] = pd.DataFrame()

