with open('../../../shared/schema_sensor.py', 'w', encoding='utf-8') as f:
    f.write('''import pandas as pd
import logging
from typing import Dict, List, Any

log = logging.getLogger(__name__)

class SchemaViolationError(Exception):
    pass

CONTRACTS: Dict[str, Dict[str, Any]] = {
    \"m3_potencial_chassi\": {
        \"required_columns\": [
            \"PIN\", \"Customer\", \"CNPJ_GRUPO\", \"Razao_Social_Grupo\", \"Model Grupo\",
            \"Horimetro_Anual_Final\", \"Horimetro_Total_Acumulado\",
            \"METODO_HORIMETRO\", \"STATUS_USO\", \"Potencial Total\"
        ],
        \"description\": \"Output granular de chassis do M3, consumido pelo M4 e M5.\"
    },
    \"m3_potencial_clientes\": {
        \"required_columns\": [
            \"CNPJ_GRUPO\", \"Razao_Social_Grupo\", \"Qtd_Maquinas\", 
            \"Horimetro_Medio\", \"Potencial Total\", \"Potencial Proporcional\"
        ],
        \"description\": \"Output agregado de clientes (Grupo Economico) do M3, consumido pelo M4.\"
    }
}

def validate_schema(df: pd.DataFrame, contract_name: str, strict: bool = False) -> bool:
    if contract_name not in CONTRACTS:
        log.warning(f\"Contrato '{contract_name}' nao definido no dicionario. Validacao ignorada.\")
        return True

    contract = CONTRACTS[contract_name]
    required_cols = set(contract[\"required_columns\"])
    actual_cols = set(df.columns)

    missing_cols = required_cols - actual_cols

    if missing_cols:
        msg = f\"Quebra de Contrato [{contract_name}]: Colunas obrigatorias ausentes: {sorted(list(missing_cols))}\"
        log.error(msg)
        if strict:
            raise SchemaViolationError(msg)
        return False

    log.info(f\"✅ Contrato [{contract_name}] validado com sucesso. Todas as {len(required_cols)} colunas obrigatorias estao presentes.\")
    return True
''')
"

