ANTIGRAVITY_ARTIFACT_FILES = ["implementation_plan.md", "walkthrough.md", "task.md"]

def get_project_name():
    """Tenta ler o nome do projeto do GEMINI.md ou usa o nome da pasta."""
    gemini_md = PROJECT_ROOT / "GEMINI.md"
    if gemini_md.exists():
        with open(gemini_md, "r", encoding="utf-8") as f:
            for line in f:
                if "PROJETO:" in line:
                    return line.split("PROJETO:")[1].strip().lower().replace(" ", "-")
    return PROJECT_ROOT.name

def encode_claude_path(path_str):
    """Codifica um path absoluto para o formato de diretÃ³rio do Claude."""
    return path_str.replace(":\\", "--").replace("\\", "-").replace(":", "--").replace("/", "-")

def is_session_for_current_project(session_dir, check_artifact_content=False):
    """Verifica se a sessÃ£o pertence ao projeto atual.
    
    EstratÃ©gia em cascata:
    1. LÃª overview.txt em .system_generated/logs/ procurando o nome do projeto.
    2. Verifica se algum .md de artefato na raiz menciona o projeto.
    3. Fallback para Gemini TMP: busca por nome de arquivo ou recÃªncia.
    """
    project_name_str = PROJECT_ROOT.name.lower()
    project_path_str = str(PROJECT_ROOT).lower()

    # 1. Overview.txt (padrÃ£o Antigravity CLI)
    overview_path = session_dir / ".system_generated" / "logs" / "overview.txt"
    if overview_path.exists():
        try:
            with open(overview_path, "r", encoding="utf-8", errors="ignore") as f:
                content = f.read().lower()
                if project_name_str in content or project_path_str in content:
                    return True
        except Exception:
            pass

    # 2. ConteÃºdo dos artefatos na raiz da sessÃ£o (Antigravity CLI)
    if check_artifact_content:
        for artifact_name in ANTIGRAVITY_ARTIFACT_FILES:
            artifact_path = session_dir / artifact_name
            if artifact_path.exists():
                try:
                    with open(artifact_path, "r", encoding="utf-8", errors="ignore") as f:
                        content = f.read().lower()
                        if project_name_str in content or project_path_str in content:
                            return True
                except Exception:
                    pass

    # 3. Fallback Gemini TMP: busca por nome de arquivo de plano ou recÃªncia
    plans_dir = session_dir / "plans"
    if plans_dir.exists():
        for f in plans_dir.iterdir():
            if project_name_str in f.name.lower():
                return True
            if (datetime.now().timestamp() - os.path.getmtime(f)) < 300:
                return True

    return False

def _has_any_artifact(session_dir):
    """Verifica se a sessÃ£o contÃ©m pelo menos um artefato conhecido."""
    for artifact_name in ANTIGRAVITY_ARTIFACT_FILES:
        if (session_dir / artifact_name).exists():
            return True
    return False


def get_latest_brain_session():
    """Localiza a sessÃ£o de brain (Antigravity) mais recente.
    
    Busca em cascata:
    1. ANTIGRAVITY_BRAIN_DIR (~/.gemini/antigravity-cli/brain) â€” path nativo atual.
    2. BRAIN_DIR (~/.shared-ai-memory/brain) â€” path legado como fallback.
    """
    # 1. Antigravity CLI nativo (path correto atual)
    if ANTIGRAVITY_BRAIN_DIR.exists():
        sessions = sorted(
            [d for d in ANTIGRAVITY_BRAIN_DIR.iterdir() if d.is_dir()],
            key=os.path.getmtime,
            reverse=True
        )
        for session in sessions:
            if _has_any_artifact(session) and is_session_for_current_project(session, check_artifact_content=True):
                return session

    # 2. Path legado (.shared-ai-memory/brain)
    if BRAIN_DIR.exists():
        sessions = sorted(
            [d for d in BRAIN_DIR.iterdir() if d.is_dir()],
            key=os.path.getmtime,
            reverse=True
        )
        for session in sessions:
            # Path legado usa subpasta 'artifacts/'
            if (session / "artifacts").exists() and is_session_for_current_project(session):
                return session

    return None

def get_latest_gemini_tmp_session():
    """Localiza a sessÃ£o de tmp (Gemini CLI) mais recente."""
    if not GEMINI_TMP_ROOT.exists():
        return None
    sessions = sorted([d for d in GEMINI_TMP_ROOT.iterdir() if d.is_dir()], key=os.path.getmtime, reverse=True)
    for session in sessions:
        if (session / "plans").exists() and is_session_for_current_project(session):
            return session
    return None

def get_claude_memory_dir():
    """Localiza a pasta de memÃ³ria nativa do Claude para o projeto atual."""
    if not CLAUDE_PROJECTS_ROOT.exists():
        return None
    
    encoded_path = encode_claude_path(str(PROJECT_ROOT))
    claude_project_dir = CLAUDE_PROJECTS_ROOT / encoded_path
    
    if claude_project_dir.exists():
        memory_dir = claude_project_dir / "memory"
        if memory_dir.exists():
            return memory_dir
            
    # Tenta match parcial (ex: C--Projetos-Inova em vez de path completo)
    for d in CLAUDE_PROJECTS_ROOT.iterdir():
        if d.is_dir() and PROJECT_ROOT.name.lower() in d.name.lower():
            memory_dir = d / "memory"
            if memory_dir.exists():
                return memory_dir
                
    return None

def promote_artifacts():
    # Coletar de todas as fontes
    sessions = []

    brain = get_latest_brain_session()
    if brain:
        # Antigravity CLI nativo: artefatos na raiz da sessÃ£o (sem subpasta artifacts/)
        # Path legado: artefatos em session/artifacts/
        is_native_antigravity = brain.parent == ANTIGRAVITY_BRAIN_DIR
        src_dir = brain if is_native_antigravity else brain / "artifacts"
        sessions.append((brain, src_dir, "antigravity"))

    tmp = get_latest_gemini_tmp_session()
    if tmp:
        sessions.append((tmp, tmp / "plans", "gemini"))

    claude_memory = get_claude_memory_dir()
    if claude_memory:
        sessions.append((claude_memory, claude_memory, "claude"))

    if not sessions:
        print(f"AVISO: Nenhuma sessÃ£o (Brain, TMP ou Claude) encontrada para o projeto {PROJECT_ROOT.name}")
        return

    date_str = datetime.now().strftime("%Y-%m-%d")
    project_name = get_project_name()
    promoted_count = 0

    for session_root, src_dir, origin in sessions:
        print(f"Verificando origem {origin}: {session_root.name}")
        
        # Mapeamento de arquivos por origem
        if origin == "antigravity":
            targets = [
                ("implementation_plan.md.resolved", "docs/plans", "plan"),
                ("implementation_plan.md", "docs/plans", "plan"),
                ("walkthrough.md", "docs/walkthroughs", "walkthrough"),
            ]
        elif origin == "gemini":
            targets = []
            for f in src_dir.glob("plan_*.md"):
                targets.append((f.name, "docs/plans", "plan"))
        else: # claude
            # Promove arquivos de memÃ³ria do Claude para docs/concepts/
            targets = []
            for f in src_dir.glob("*.md"):
                targets.append((f.name, "docs/concepts", "concept_claude"))

        for src_name, dest_subfolder, type_prefix in targets:
            src_path = src_dir / src_name
            if src_path.exists():
                dest_dir = PROJECT_ROOT / dest_subfolder
                dest_dir.mkdir(parents=True, exist_ok=True)

                # Formato do nome: prefixo_projeto_nomeoriginal.md
                # Para Claude, mantemos o nome original com prefixo
                if origin == "claude":
                    new_filename = f"{type_prefix}_{src_name}"
                else:
                    new_filename = f"{type_prefix}_{date_str}_{project_name}.md"
                
                dest_path = dest_dir / new_filename

                counter = 1
                while dest_path.exists():
                    if filecmp.cmp(src_path, dest_path, shallow=False):
                        print(f"  [SKIP] {new_filename} (sem mudanÃ§as)")
                        break
                    counter += 1
                    if origin == "claude":
                         new_filename = f"{type_prefix}_{src_name.replace('.md', '')}_v{counter}.md"
                    else:
                         new_filename = f"{type_prefix}_{date_str}_{project_name}_v{counter}.md"
                    dest_path = dest_dir / new_filename

                if not dest_path.exists():
                    shutil.copy2(src_path, dest_path)
                    print(f"  [OK] PROMOVIDO: {src_name} -> {dest_subfolder}/{new_filename}")
                    promoted_count += 1

    print(f"\nResumo: {promoted_count} artefatos sincronizados.")

if __name__ == "__main__":
    print(f"--- Stout Artifact Promoter v2.2 ---")
    promote_artifacts()
